(async () => {
  try {
    const me = String(Inputs.userId || '');
    const name = String(Inputs.name || '');
    if (!me || !name) throw new Error('missing user or name');
    const rows = await Noodl.Records.query('_Files', { storedName: { equalTo: name } }, { limit: 2, plain: true });
    const owner = rows.length === 1 ? rows[0].owner : null;
    const ownerId = owner && typeof owner === 'object' ? owner.objectId : owner;
    if (ownerId !== me) throw new Error('not your file');
    Outputs.name = name;
  } catch (e) {
    console.error('[dbu:fileLink]', String((e && e.message) || e));
    Outputs.refused();
  }
})();
